import unittest

from solution import reflow_lines


class ReflowLinesTests(unittest.TestCase):
    def test_empty_and_whitespace_only_inputs(self):
        self.assertEqual(reflow_lines([]), "")
        self.assertEqual(reflow_lines(["", "   ", "\t\n"]), "")

    def test_trims_and_joins_ordinary_lines(self):
        lines = ["  The first line  ", "\tcontinues here\n", " and ends. "]
        before = list(lines)
        self.assertEqual(reflow_lines(lines), "The first line continues here and ends.")
        self.assertEqual(lines, before)

    def test_empty_lines_make_single_paragraph_break(self):
        lines = ["first", "", "  ", "\t", "second", "", "third"]
        self.assertEqual(reflow_lines(lines), "first\n\nsecond\n\nthird")

    def test_trailing_single_hyphen_joins_without_space(self):
        self.assertEqual(reflow_lines(["hyphen-", "ated word"]), "hyphenated word")
        self.assertEqual(reflow_lines(["one line", "inter-", "ruption"]), "one line interruption")

    def test_hyphenated_join_respects_trimming(self):
        self.assertEqual(reflow_lines(["  pre-  ", "  fix  "]), "prefix")

    def test_generator_input(self):
        lines = (line for line in ["alpha", "beta", "", "gamma"])
        self.assertEqual(reflow_lines(lines), "alpha beta\n\ngamma")

    def test_non_string_entry_raises_type_error(self):
        for bad in (None, 1, True, [], {}):
            with self.subTest(bad=bad):
                with self.assertRaises(TypeError):
                    reflow_lines(["valid", bad, "later"])


if __name__ == "__main__":
    unittest.main()

